class Problem {final String question,explanation;final int answer;final List<int> options;const Problem(this.question,this.answer,this.explanation,this.options);}
Problem problem(int id){final m=id~/25,step=id%25;final a=2+(step*3+m)%16,b=1+(step*7+m)%9;int ans;String q,tip;switch(m){case 0:ans=a;q='$a sonidan keyingi son qaysi?';ans=a+1;tip='Sonlar ketma-ketligida har bir keyingi son oldingisidan 1 taga katta.';break;case 1:ans=a+b;q='$a + $b = ?';tip='Qo‘shishda sonlarni birlashtiramiz.';break;case 2:ans=a+b-b;q='${a+b} − $b = ?';tip='Ayirishda umumiy sondan bir qismini olib tashlaymiz.';break;case 3:ans=a*b;q='$a × $b = ?';tip='Ko‘paytirish — bir xil sonni takror qo‘shish.';break;case 4:ans=a;q='${a*b} ÷ $b = ?';tip='Bo‘lishda teng guruhlarga ajratamiz.';break;case 5:ans=max(a,b);q='$a va $b sonlaridan kattasi qaysi?';tip='Sonlar chizig‘ida o‘ngroqda joylashgan son kattaroq.';break;case 6:ans=[3,4,4,0][step%4];q=['Uchburchakning nechta tomoni bor?','Kvadratning nechta tomoni bor?','To‘g‘ri to‘rtburchakning nechta burchagi bor?','Aylananing nechta burchagi bor?'][step%4];tip='Shaklning tomonlari va burchaklarini sanaymiz.';break;case 7:ans=a*10;q='$a santimetr necha millimetr?';tip='1 santimetr = 10 millimetr.';break;case 8:ans=a+b;q='Alida $a ta qalam bor. Yana $b ta qalam oldi. Jami nechta?';tip='Jami sonni topish uchun qo‘shamiz.';break;default:ans=a+2;q='$a, ${a+1}, ?, ${a+3}. Yetishmayotgan son?';tip='Har safar son 1 taga ortmoqda.';}return Problem(q,ans,tip,[ans,ans+1,ans+2,max(0,ans-1)]..shuffle(Random(id+7)));}
